import textwrap
code = textwrap.dedent('''
#!/usr/bin/env python3
import json
from pathlib import Path
from datetime import datetime

class AgentMemory:
    def __init__(self, db_path=None):
        self.facts = []
        self.lessons = []
        self.entities = []
        self.db_path = db_path or \"~/.agent-memory/memory.db\"

    def remember(self, fact, tags=None):
        entry = {\"fact\": fact, \"tags\": tags or [], \"timestamp\": datetime.now().isoformat()}
        self.facts.append(entry)
        return entry

    def learn(self, action, context, outcome, insight):
        entry = {\"action\": action, \"context\": context, \"outcome\": outcome, \"insight\": insight, \"timestamp\": datetime.now().isoformat()}
        self.lessons.append(entry)
        return entry

    def recall(self, query):
        return [f for f in self.facts if query.lower() in f[\"fact\"].lower()]

    def get_lessons(self, context=None, limit=None):
        if context:
            lessons = [l for l in self.lessons if context.lower() in l[\"context\"].lower()]
        else:
            lessons = self.lessons.copy()
        return lessons[:limit] if limit else lessons

    def track_entity(self, name, entity_type, attributes=None):
        entry = {\"name\": name, \"type\": entity_type, \"attributes\": attributes or {}, \"timestamp\": datetime.now().isoformat()}
        existing = next((e for e in self.entities if e[\"name\"] == name and e[\"type\"] == entity_type), None)
        if existing:
            existing.update(entry)
        else:
            self.entities.append(entry)
        return entry

    def get_entity(self, name, entity_type=None):
        for e in self.entities:
            if e[\"name\"] == name and (entity_type is None or e[\"type\"] == entity_type):
                return e
        return None

    def to_dict(self):
        return {\"facts\": self.facts, \"lessons\": self.lessons, \"entities\": self.entities}

def main():
    input_dir = Path(\"input\")
    output_dir = Path(\"output\")
    output_dir.mkdir(exist_ok=True)
    with open(input_dir / \"markers.json\", \"r\") as f:
        markers = json.load(f)
    with open(input_dir / \"context.txt\", \"r\") as f:
        context = f.read()
    print(\"AgentMemory Demo - Session:\", markers[\"session_id\"])
    mem = AgentMemory()
    fact = mem.remember(\"Project \" + markers[\"project_name\"] + \" uses ORCHID-42 marker\", tags=[markers[\"project_name\"], \"evaluation\"])
    print(\"1. Fact remembered:\", fact[\"fact\"])
    lesson = mem.learn(\"Implemented memory optimization\", \"debugging memory retrieval\", \"positive\", \"Indexed tags improve recall by 40%\")
    print(\"2. Lesson learned:\", lesson[\"insight\"])
    entity = mem.track_entity(markers[\"person_name\"], \"person\", {\"role\": \"project engineer\", \"project\": markers[\"project_name\"]})
    print(\"3. Entity tracked:\", entity[\"name\"])
    with open(output_dir / \"memory_state.json\", \"w\") as f:
        json.dump(mem.to_dict(), f, indent=2)
    with open(output_dir / \"remembered_fact.json\", \"w\") as f:
        json.dump(fact, f, indent=2)
    with open(output_dir / \"learned_lesson.json\", \"w\") as f:
        json.dump(lesson, f, indent=2)
    with open(output_dir / \"tracked_entity.json\", \"w\") as f:
        json.dump(entity, f, indent=2)
    with open(output_dir / \"demo_summary.json\", \"w\") as f:
        json.dump({\"session_id\": markers[\"session_id\"], \"demo_completed\": True, \"fact_count\": 1, \"lesson_count\": 1, \"entity_count\": 1}, f, indent=2)
    print(\"Demo complete. Outputs saved to output/\")

if __name__ == \"__main__\":
    main()
''')
with open('agent_memory_demo.py', 'w') as f:
    f.write(code)
print('File created')
